-- Kehadiran harian September (impor mesin) dan 1-14 Oktober (ESS).
INSERT INTO employee_attendance (school_id, employee_id, work_date, status, check_in_at, check_out_at, source, import_batch_id, note)
SELECT '11111111-1111-1111-1111-111111111111', e.id, d::date,
       CASE WHEN (extract(day FROM d)::int + e.n) % 11 = 0 THEN 'terlambat'
            WHEN (extract(day FROM d)::int * e.n) % 29 = 7 THEN 'izin'
            ELSE 'hadir' END,
       CASE WHEN (extract(day FROM d)::int * e.n) % 29 = 7 THEN NULL
            ELSE (d + CASE WHEN (extract(day FROM d)::int + e.n) % 11 = 0 THEN TIME '07:24' ELSE TIME '06:48' + ((extract(day FROM d)::int * e.n) % 14) * INTERVAL '1 minute' END)
                 AT TIME ZONE 'Asia/Jakarta' END,
       CASE WHEN (extract(day FROM d)::int * e.n) % 29 = 7 THEN NULL
            ELSE (d + TIME '15:10' + ((extract(day FROM d)::int + e.n) % 25) * INTERVAL '1 minute') AT TIME ZONE 'Asia/Jakarta' END,
       CASE WHEN d < '2026-10-01' THEN 'import' ELSE 'ess' END,
       CASE WHEN d < '2026-10-01' THEN '5000000a-0000-4000-8000-000000000002'::uuid END,
       CASE WHEN (extract(day FROM d)::int * e.n) % 29 = 7 THEN 'Izin keperluan keluarga'
            WHEN (extract(day FROM d)::int + e.n) % 11 = 0 THEN 'Terlambat (macet)' END
FROM (VALUES ('93000000-0000-0000-0000-000000000001'::uuid, 1, '2024-07-01'::date),
             ('93000000-0000-0000-0000-000000000002'::uuid, 2, '2025-01-10'),
             ('50000003-0000-4000-8000-000000000003'::uuid, 3, '2019-07-15'),
             ('50000003-0000-4000-8000-000000000004'::uuid, 4, '2025-08-01'),
             ('50000003-0000-4000-8000-000000000005'::uuid, 5, '2023-01-09'),
             ('50000003-0000-4000-8000-000000000006'::uuid, 6, '2018-03-01'),
             ('50000003-0000-4000-8000-000000000007'::uuid, 7, '2026-10-01')) AS e(id, n, hired)
CROSS JOIN generate_series('2026-09-01'::timestamp, '2026-10-14'::timestamp, INTERVAL '1 day') AS d
WHERE extract(isodow FROM d) BETWEEN 1 AND 5
  AND d::date >= e.hired
  AND NOT EXISTS (SELECT 1 FROM holidays h WHERE h.school_id = '11111111-1111-1111-1111-111111111111' AND h.date = d::date)
ON CONFLICT DO NOTHING;

