-- payroll_input_changes ada di migrasi 0010 lokal tetapi belum ada di
-- server (drift skema), jadi hanya diisi bila tabelnya ada.
DO $$
BEGIN
  IF to_regclass('public.payroll_input_changes') IS NOT NULL THEN
    EXECUTE $q$
      INSERT INTO payroll_input_changes (id, school_id, input_id, period, employee_id, component_id, before_amount_idr, after_amount_idr, reason, status, created_at, updated_at) VALUES
       ('5000003a-0000-4000-8000-000000000001', '11111111-1111-1111-1111-111111111111', '50000014-0000-4000-8000-000000001002', '2026-10', '93000000-0000-0000-0000-000000000001', '50000010-0000-4000-8000-000000000005', 250000, 400000, 'Penambahan cicilan pinjaman koperasi mulai Oktober', 'pending_approval', '2026-10-14 11:00:00+07', '2026-10-14 11:00:00+07'),
       ('5000003a-0000-4000-8000-000000000002', '11111111-1111-1111-1111-111111111111', '50000014-0000-4000-8000-000000000901', '2026-09', '50000003-0000-4000-8000-000000000005', '50000010-0000-4000-8000-000000000003', 770000, 840000, 'Koreksi jam tambahan: 2 jam pengganti guru cuti', 'approved', '2026-09-24 11:00:00+07', '2026-09-24 15:00:00+07'),
       ('5000003a-0000-4000-8000-000000000003', '11111111-1111-1111-1111-111111111111', '50000014-0000-4000-8000-000000001003', '2026-10', '50000003-0000-4000-8000-000000000006', '50000010-0000-4000-8000-000000000005', 150000, 0, 'Pinjaman koperasi dinyatakan lunas', 'rejected', '2026-10-13 09:00:00+07', '2026-10-13 14:00:00+07')
