-- Tahapan default (sama dengan EnsureDefaultStages) hanya bila sekolah
-- belum punya tahapan sama sekali.
INSERT INTO pipeline_stages (id, school_id, code, name, sort, kind)
SELECT s.id::uuid, '11111111-1111-1111-1111-111111111111', s.code, s.name, s.sort, s.kind
FROM (VALUES ('50000028-0000-4000-8000-000000000001', 'screening', 'Screening Berkas', 1, 'normal'),
             ('50000028-0000-4000-8000-000000000002', 'interview', 'Wawancara', 2, 'normal'),
             ('50000028-0000-4000-8000-000000000003', 'microteaching', 'Microteaching / Tes Teknis', 3, 'normal'),
             ('50000028-0000-4000-8000-000000000004', 'offer', 'Penawaran Kerja', 4, 'offer'),
             ('50000028-0000-4000-8000-000000000005', 'hired', 'Diterima (Hired)', 5, 'hired'),
             ('50000028-0000-4000-8000-000000000006', 'rejected', 'Tidak Lolos', 6, 'rejected')) AS s(id, code, name, sort, kind)
WHERE NOT EXISTS (SELECT 1 FROM pipeline_stages p WHERE p.school_id = '11111111-1111-1111-1111-111111111111' AND p.deleted_at IS NULL)
ON CONFLICT DO NOTHING;

-- Peta kode tahap -> id tahap yang berlaku di sekolah (dipakai di bawah).
CREATE TEMP TABLE seed50_stage ON COMMIT DROP AS
SELECT DISTINCT ON (code) code, id FROM pipeline_stages
WHERE school_id = '11111111-1111-1111-1111-111111111111' AND deleted_at IS NULL
ORDER BY code, sort, created_at;

