-- Nilai panel untuk wawancara/microteaching yang sudah selesai.
INSERT INTO interview_scores (id, school_id, interview_id, panel_user_id, criterion_id, score, recommendation, submitted_at, created_at)
SELECT ('50000031-0000-4000-8000-000000' || right(i.id::text, 2) || p.n || right(c.id::text, 3))::uuid,
       i.school_id, i.id, p.uid, c.id,
       LEAST(100, s.base + p.adj + (right(c.id::text, 1)::int * 3) - 3),
       CASE WHEN s.base >= 80 THEN 'Direkomendasikan' WHEN s.base >= 70 THEN 'Dipertimbangkan' ELSE 'Tidak direkomendasikan' END,
       i.ends_at + INTERVAL '30 minutes', i.ends_at + INTERVAL '30 minutes'
FROM interviews i
JOIN (VALUES ('5000002f-0000-4000-8000-000000000001', 84), ('5000002f-0000-4000-8000-000000000002', 90),
             ('5000002f-0000-4000-8000-000000000003', 86), ('5000002f-0000-4000-8000-000000000004', 72),
             ('5000002f-0000-4000-8000-000000000008', 88)) AS s(iid, base) ON s.iid::uuid = i.id
JOIN scorecard_criteria c ON c.template_id = i.template_id
CROSS JOIN (VALUES ('1', '22222222-2222-2222-2222-222222222222'::uuid, 0), ('2', '77777777-7777-7777-7777-777777777777'::uuid, 2)) AS p(n, uid, adj)
WHERE i.status = 'done'
ON CONFLICT DO NOTHING;

