-- ---------------------------------------------------------------------------
-- 7. Payroll run, baris gaji, slip, jurnal, setoran pajak.
--    Dihasilkan dengan engine payroll layanan HR (CalculateRun/FinalizeRun)
--    memakai gaji pokok contoh: 2026-07 & 2026-08 final (sudah dibayar,
--    slip terbit, jurnal terposting), 2026-08 susulan ditolak, 2026-09
--    approved (menunggu finalisasi), 2026-10 draft (belum dihitung).
--    Dilewati seluruhnya bila sekolah sudah punya run reguler lain untuk
--    periode tersebut, sehingga data payroll yang ada tidak tersentuh.
-- ---------------------------------------------------------------------------
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM payroll_runs
             WHERE school_id = '11111111-1111-1111-1111-111111111111' AND kind = 'regular'
               AND period IN ('2026-07', '2026-08', '2026-09', '2026-10')
               AND status NOT IN ('rejected', 'cancelled')
               AND id::text NOT LIKE '50000015-%') THEN
    RAISE NOTICE 'Run payroll reguler 2026-07..10 sudah ada; seed run payroll dilewati.';
    RETURN;
  END IF;
