  -- tax_remittances: setoran PPh 21 & BPJS dari run final
  INSERT INTO tax_remittances (id, school_id, period, kind, amount_idr, paid_on, ref, created_at)
  SELECT ('50000018-0000-4000-8000-0000000' || substr(r.period, 6, 2) || '00' || k.n)::uuid, r.school_id, r.period, k.kind,
         SUM(CASE k.kind
               WHEN 'pph21' THEN l.pph21_idr
               WHEN 'bpjs_kesehatan' THEN (l.details->'bpjs'->'employee'->>'kesehatan')::bigint + (l.details->'bpjs'->'employer'->>'kesehatan')::bigint
               ELSE l.bpjs_employee_idr + l.bpjs_employer_idr
                    - (l.details->'bpjs'->'employee'->>'kesehatan')::bigint - (l.details->'bpjs'->'employer'->>'kesehatan')::bigint
             END),
         (to_date(r.period, 'YYYY-MM') + INTERVAL '1 month' + INTERVAL '9 days')::date,
         k.prefix || replace(r.period, '-', ''),
         to_date(r.period, 'YYYY-MM') + INTERVAL '1 month' + INTERVAL '9 days 10 hours'
  FROM payroll_runs r
  JOIN payroll_lines l ON l.run_id = r.id
  CROSS JOIN (VALUES ('1', 'pph21', 'NTPN-PPH21-'), ('2', 'bpjs_kesehatan', 'BPJSKES-'), ('3', 'bpjs_tk', 'BPJSTK-')) AS k(n, kind, prefix)
  WHERE r.id IN ('50000015-0000-4000-8000-000000000007', '50000015-0000-4000-8000-000000000008')
  GROUP BY r.id, r.school_id, r.period, k.n, k.kind, k.prefix
  ON CONFLICT DO NOTHING;
END $$;

COMMIT;
